// Import the crypto module here
const crypto = require('crypto');

// Create the assignABTest function here
function assignABTest(userId, testId) {
  // Create configuration object with variants A and B, each weight 0.5
  const config = {
    A: 0.5,
    B: 0.5
  };

  // Create deterministic hash function here
  function deterministicHash(str) {
    return crypto.createHash('md5').update(str).digest().readUInt32BE(0);
  }

  // Call hash function with userId and testId and store result
  const hashValue = deterministicHash(userId + testId);

  // Convert hash to percentage here
  const percentage = hashValue / Math.pow(2, 32);

  // Add weighted assignment logic here
  let cumulative = 0;
  for (const variant in config) {
    cumulative += config[variant];
    if (percentage < cumulative) {
      return variant;
    }
  }

  // Return the assigned variant here
  return 'A';
}

